<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { api,useLoad,can,money,PageHeader,Feedback,EmptyState,StatusBadge,type Aftersale } from '@tradeflow/ui'
import { pathNo } from '../state'
const before=ref(''),history=ref<string[]>([]),lookup=ref('');const load=useLoad<Aftersale[]>(s=>api(`/aftersales?limit=12${before.value?`&before=${pathNo(before.value)}`:''}`,{signal:s}));onMounted(()=>{if(can('AFTERSALES'))void load.reload()})
async function next(){if(!load.data.value?.length)return;history.value.push(before.value);before.value=load.data.value[load.data.value.length-1]!.aftersaleNo;await load.reload()}
async function prev(){before.value=history.value.pop() || '';await load.reload()}
</script>
<template><section><PageHeader title="售后服务" description="申请、审核、退货与退款，在这里保持同步。"><template #actions><button :disabled="!can('AFTERSALES')" @click="load.reload()">刷新进度</button></template></PageHeader><form class="lookup" @submit.prevent><label for="aftersale-lookup">按售后号查看</label><input id="aftersale-lookup" v-model.trim="lookup" placeholder="输入完整售后编号"/><RouterLink v-if="lookup" class="button secondary" :to="`/aftersales/${pathNo(lookup)}`">查看售后</RouterLink></form><Feedback :error="load.error.value" :loading="load.loading.value"/><EmptyState v-if="load.data.value && !load.data.value.length" title="暂无售后记录" description="如需售后，请进入对应订单，查看当前可申请的类型。"><RouterLink class="button secondary" to="/orders">前往我的订单</RouterLink></EmptyState><article v-for="a in load.data.value" :key="a.aftersaleNo" class="panel"><div class="row spread"><div><span class="eyebrow">{{a.type==='UNSHIPPED_FULL'?'未发货整单退款':a.type==='REFUND_ONLY'?'仅退款':'退货退款'}}</span><h2 class="mono small">{{a.aftersaleNo}}</h2></div><StatusBadge :status="a.status"/></div><p class="muted">{{a.reason}}</p><div class="row spread"><strong class="price">{{a.amountCents===null?'金额确认中':money(a.amountCents)}}</strong><RouterLink class="button secondary" :to="`/aftersales/${pathNo(a.aftersaleNo)}`">查看详情与材料</RouterLink></div></article><div v-if="load.data.value" class="pagination"><button :disabled="!history.length" @click="prev">上一页</button><span>第 {{history.length+1}} 页</span><button :disabled="load.data.value.length<12" @click="next">下一页</button></div></section></template>
